1	/**
2	 * Wave 1 games — make ARK, Satisfactory, Project Zomboid, 7 Days to Die, V Rising
3	 * and Enshrouded orderable. Each is a Docker container (community image) installed
4	 * by the OsTemplate.setupScript in cloud-init — same pattern as Minecraft/Rust/Valheim.
5	 *
6	 * Creates:
7	 *   1. An OsTemplate per game (family=<game>, category=APPLICATION, setupScript = the
8	 *      one-line docker run). Clones the golden Ubuntu template (baseVmid 9000).
9	 *   2. GamePlan tiers, each wired to the smallest active VPS Plan whose ramMB >= the
10	 *      tier's ramMB + this game's OsTemplate.
11	 *
12	 * Idempotent: OsTemplates upsert by slug; GamePlans dedupe by (gameFamily, name).
13	 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave1-games.ts
14	 *
15	 * NOTE: default in-container passwords are the static placeholder "changeme12"
16	 * (matching the existing Valheim template) — customers change them post-deploy.
17	 * A per-order random-secret injection is a follow-up security refinement.
18	 */
19	import { PrismaClient } from "@prisma/client";
20	
21	const db = new PrismaClient();
22	
23	type Template = {
24	  family: string;
25	  name: string;
26	  setupScript: string;
27	  minRamMB: number;
28	  minDiskGB: number;
29	};
30	
