34	    name: "ARK: Survival Evolved Server",
35	    minRamMB: 8192,
36	    minDiskGB: 40,
37	    setupScript:
38	      `curl -fsSL https://get.docker.com | sh && docker run -d --name ark -e SESSION_NAME="Nxeon" -e SERVER_MAP=TheIsland -e SERVER_PASSWORD="changeme12" -e ADMIN_PASSWORD="changeme12" -e MAX_PLAYERS=20 -p 7777:7777/udp -p 7778:7778/udp -p 27015:27015/udp -p 27020:27020/tcp -v /opt/ark:/app --restart unless-stopped hermsi/ark-server:latest`,
39	  },
40	  {
41	    family: "satisfactory",
42	    name: "Satisfactory Server",
43	    minRamMB: 8192,
44	    minDiskGB: 20,
45	    setupScript:
46	      `curl -fsSL https://get.docker.com | sh && docker run -d --name satisfactory -e MAXPLAYERS=4 -e PUID=1000 -e PGID=1000 -e STEAMBETA=false -e AUTOSAVENUM=5 -e MAXTICKRATE=30 -p 7777:7777/tcp -p 7777:7777/udp -p 8888:8888/tcp -v /opt/satisfactory:/config --restart unless-stopped wolveix/satisfactory-server:latest`,
47	  },
48	  {
49	    family: "projectzomboid",
50	    name: "Project Zomboid Server",
51	    minRamMB: 6144,
52	    minDiskGB: 15,
53	    setupScript:
54	      `curl -fsSL https://get.docker.com | sh && docker run -d --name projectzomboid -e PUID=1000 -e PGID=1000 -p 16261:16261/udp -p 16262:16262/udp -p 27015:27015/tcp -e SERVER_NAME=servertest -e SERVER_BRANCH= -e ADMIN_USERNAME=admin -e ADMIN_PASSWORD=changeme12 -e RCON_PASSWORD=changeme12 -e MAX_PLAYERS=16 -v /opt/projectzomboid/config:/project-zomboid-config -v /opt/projectzomboid/server:/project-zomboid --restart unless-stopped indifferentbroccoli/projectzomboid-server-docker`,
55	  },
56	  {
57	    family: "sdtd",
58	    name: "7 Days to Die Server",
59	    minRamMB: 8192,
60	    minDiskGB: 25,
61	    setupScript:
62	      `curl -fsSL https://get.docker.com | sh && docker run -d --name sdtd -p 26900:26900/tcp -p 26900:26900/udp -p 26901:26901/udp -p 26902:26902/udp -e START_MODE=1 -e VERSION=stable -e PUID=1000 -e PGID=1000 -e TimeZone=UTC -v /opt/sdtd/serverfiles:/home/sdtdserver/serverfiles -v /opt/sdtd/saves:/home/sdtdserver/.local/share/7DaysToDie -v /opt/sdtd/lgsm-config:/home/sdtdserver/lgsm/config-lgsm/sdtdserver -v /opt/sdtd/log:/home/sdtdserver/log --restart unless-stopped vinanrra/7dtd-server`,
63	  },
64	  {
65	    family: "vrising",
66	    name: "V Rising Server",
67	    minRamMB: 6144,
68	    minDiskGB: 20,
69	    setupScript:
